import urllib.request,concurrent.futures,json
urls={
'build':'https://raw.githubusercontent.com/akiyamalab/MEGADOCK/4.1.4/doc/BUILD.md',
'usage':'https://raw.githubusercontent.com/akiyamalab/MEGADOCK/4.1.4/doc/README.md',
'make':'https://raw.githubusercontent.com/akiyamalab/MEGADOCK/4.1.4/Makefile',
