'pinder_readme':'https://raw.githubusercontent.com/pinder-org/pinder/ebeb28a2f8411363cef722b7d293c978f7442672/README.md',
'release':'https://api.github.com/repos/akiyamalab/MEGADOCK/git/ref/tags/4.1.4',
}
def get(kv):
 k,u=kv
 try:
  with urllib.request.urlopen(u,timeout=25) as r:t=r.read().decode()
  return k,{'url':u,'text':t}
 except Exception as e:return k,{'url':u,'error':str(e)}
r=dict(concurrent.futures.ThreadPoolExecutor(8).map(get,urls.items()))
open('intake/sources.json','w').write(json.dumps(r,indent=2))
for k,v in r.items():
 print('\\nSOURCE',k,v['url'])
 print(v.get('error',v.get('text',''))[:23000 if k in ['build','usage','make'] else 6000])
PY"

