/bin/bash -lc "python3 - <<'PY'
import json,urllib.request,re,concurrent.futures,hashlib
p='intake/sources.json';s=json.load(open(p));t=s['pinder_readme']['text']
for m in re.finditer('licen|DockQ|pinder_eval',t,re.I): print(t[max(0,m.start()-180):m.start()+650])
u='https://api.github.com/repos/akiyamalab/MEGADOCK/git/tags/1ced00d37672c03d3014da4307b920fdeff4d0ca'
try:
 with urllib.request.urlopen(u,timeout=20) as r:s['tag']={'url':u,'text':r.read().decode()}
 print('TAG',s['tag']['text'])
except Exception as e:print(str(e))
b=open('intake/brief.md').read();rows=[]
for line in b.splitlines():
 if '| https://pinderdata.org/2024-02/pdbs/' in line and 'official_original_location' in line:
  cells=[x.strip().strip('"'`'"') for x in line.split('|')[1:-1]]
  if any(x in cells[0] for x in ['6f0e__A1','3n35__A1','3g8c__A1','3g8d__A1','1sg6__A1','--']):rows.append(cells)
def check(c):
 try:
  with urllib.request.urlopen(c[1],timeout=25) as r: raw=r.read()
  return {'url':c[1],'status':'accessible','bytes':len(raw),'sha256':hashlib.sha256(raw).hexdigest(),'recorded_sha256':c[-1],'hash_matches_brief':hashlib.sha256(raw).hexdigest()==c[-1]}
 except Exception as e:return {'url':c[1],'status':'unreachable','reason':str(e)}
s['required_structures_checks']=list(concurrent.futures.ThreadPoolExecutor(9).map(check,rows))
print(json.dumps(s['required_structures_checks'],indent=2))
json.dump(s,open(p,'w'),indent=2)
PY"

